import{_ as s,C as t,o,c as i,E as r,a2 as h}from"./chunks/framework.BdWD-ld-.js";const d="/joinwell52/assets/sop-handoff-20261124/verdict-reader-v2.en.svg",v=JSON.parse('{"title":"An AI worker takes over. Which rent report would you approve?","description":"Why do two reports on the same payment get opposite verdicts? Twelve comparisons, one missing-file check, and a paired follow-up trace which rules and evidence should survive an agent handoff.","frontmatter":{"title":"An AI worker takes over. Which rent report would you approve?","description":"Why do two reports on the same payment get opposite verdicts? Twelve comparisons, one missing-file check, and a paired follow-up trace which rules and evidence should survive an agent handoff.","cover":"/assets/covers/2026-11-24-sop-version-handoff-reader-v2.png","date":"2026-11-24","published_date":"2026-11-24","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"en","lifecycle":"Published","publication_authorized":true,"lang":"en-US","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-24-sop-version-handoff.md","filePath":"en/research/2026-11-24-sop-version-handoff.md","lastUpdated":1795507861000}'),c={name:"en/research/2026-11-24-sop-version-handoff.md"};function l(p,e,g,u,w,f){const a=t("ArticleCover"),n=t("ArticleTableScroll");return o(),i("div",null,[r(a,{image:"/assets/covers/2026-11-24-sop-version-handoff-reader-v2.png",kicker:"Digital employees · Handoff and review",title:"An AI worker takes over. Which rent report would you approve?",summary:"Why do two reports on the same payment get opposite verdicts? Twelve comparisons, one missing-file check, and a paired follow-up trace which rules and evidence should survive an agent handoff.",version:"2026-11-24",languageHref:"/zh/research/2026-11-24-sop-version-handoff",languageLabel:"简体中文"}),r(n,{language:"en"}),e[0]||(e[0]=h('<h1 id="an-ai-worker-takes-over-which-rent-report-would-you-approve" tabindex="-1">An AI worker takes over. Which rent report would you approve? <a class="header-anchor" href="#an-ai-worker-takes-over-which-rent-report-would-you-approve" aria-label="Permalink to &quot;An AI worker takes over. Which rent report would you approve?&quot;">​</a></h1><p>Imagine a company assigning rent reconciliation to AI digital employees. <strong>A digital employee is an AI agent that takes responsibility for a role.</strong> Like a person given an assignment, the reconciliation agent has to understand the job, plan the work, find evidence, resolve questions, and explain its result. At shift change, another digital employee takes over and a separate reviewer decides whether the report should pass.</p><p><strong>That’s the scenario we tested.</strong> In the actual runs, we used scripted stand-ins for the agents and a test identity to record approval. No humans changed shifts and no language model was called. We ran the real <strong>CodeFlowMu</strong> interfaces. CodeFlowMu is the local AI team coordination system we develop. It manages assignments, approval decisions, reports, and reviews.</p><p>The digital employees for these roles are still in development. This synthetic account gives us a way to work out what their role skills and tools should provide. What evidence does the next agent need to carry on independently, and what does a separate reviewer need to check its work?</p><p>Take the reviewer’s seat. Two reports show the same rent payment. The tenant owes <strong>¥3,000</strong>, the bank received <strong>¥2,700</strong>, and a <strong>¥300 waiver</strong> is still provisional. Nobody has signed off on the waiver.</p><p>When the morning shift assigned the work, only approved waivers counted. That afternoon, the procedure changed to include provisional waivers. One line in the assignment reads: “Finish this attempt under the procedure in effect at dispatch.”</p><table tabindex="0"><thead><tr><th>Report</th><th>What it says</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Count the provisional waiver. <strong>¥0 outstanding.</strong> The account is reconciled.</td></tr><tr><td><strong>B</strong></td><td>Keep the provisional waiver open. <strong>¥300 outstanding</strong> until it’s approved.</td></tr></tbody></table><p><strong>Would you approve A or B?</strong> Make your call, then see what happened when the reviewer opened the afternoon procedure.</p><details><summary>I’ve made my choice. Show the result.</summary><p>For this assignment, <strong>B</strong> should pass. In the experiment, a reviewer recalculating under the latest procedure did exactly the opposite: <strong>A passed and B was rejected.</strong></p><h2 id="the-reviewer-did-the-math-and-still-got-it-backwards" tabindex="-1">The reviewer did the math and still got it backwards <a class="header-anchor" href="#the-reviewer-did-the-math-and-still-got-it-backwards" aria-label="Permalink to &quot;The reviewer did the math and still got it backwards&quot;">​</a></h2><p>The review program recalculated from the source records. Under the new rule, the provisional waiver counts. Subtract ¥2,700 and then ¥300 from ¥3,000, and the balance is zero. The program compared Report B’s ¥300 balance with its own zero and rejected it. Report B had used the version specified on the original assignment.</p><p>The question is who changed the rule for this assignment. The morning instructions left ¥300 pending. After the afternoon update, the worker opened the latest procedure, and so did the reviewer. Both calculations were internally correct. <strong>On that path, publishing a procedure silently changed the acceptance criteria for work already underway.</strong> The reviewer recalculated under the same new rule and ratified the change. Add another reviewer who also opens only the latest copy, and you may get one more vote for the same mistake.</p><h2 id="same-procedure-id-which-page-opens" tabindex="-1">Same procedure ID. Which page opens? <a class="header-anchor" href="#same-procedure-id-which-page-opens" aria-label="Permalink to &quot;Same procedure ID. Which page opens?&quot;">​</a></h2><p>The starting point was a fix in <strong>StaffDeck</strong>, OpenBMB’s open-source platform for enterprise digital employees. It publishes operating procedures for AI agents. The problem was an old database migration that ran at startup. In the regression example, an agent found the expense policy under <code>sop_expense_policy</code>. The migration could rename the stored ID to <code>skill_expense_policy</code> while the published reference still pointed to the original ID. The procedure could still be in the database while the agent lost sight of it. The fix preserves published IDs and restores previously renamed IDs when it can establish the match without a conflict.</p><p>The regression test publishes a procedure, reopens the database, and runs initialization. It tries two cases: the public ID is still intact, or the old logic has already renamed it. In both cases it checks that the original ID is present and the procedure is visible to the agent. That test answers <strong>“Can the agent still find this procedure?”</strong> It gave us a follow-up question. If the ID still works but someone publishes a revision in the afternoon, how does the evening shift open the version that applies to the morning assignment? That is why we put Reports A and B side by side. <a href="https://github.com/OpenBMB/StaffDeck/commit/389d5d331cf40eb5f0aae83c4fa24f4ed10b0003" target="_blank" rel="noreferrer">StaffDeck’s change and regression test</a></p><p>StaffDeck’s fix shows why the next digital employee needs to be able to retrieve the procedure. We took that question two steps further. First we kept the procedure ID stable and updated the text after dispatch, to see whether the worker and reviewer would make the same version mistake. Then we approved a switch for only one open assignment and checked whether the next shift could keep the verified payment and reassess just the waiver. The first test asks whether the rule can change silently. The second asks whether a deliberate switch can limit the rework to its approved scope.</p><h2 id="the-first-six-all-passed-why-run-six-more" tabindex="-1">The first six all passed. Why run six more? <a class="header-anchor" href="#the-first-six-all-passed-why-run-six-more" aria-label="Permalink to &quot;The first six all passed. Why run six more?&quot;">​</a></h2><p>We simulated the two roles in CodeFlowMu, keeping the rent data and the instruction to finish under the original rule constant. The worker program either opened the current procedure or retrieved the assigned copy. The review program read back the report and task under its own test identity, then checked each report twice: recalculate the amount under the current procedure, or check the version, file fingerprint, and amount against the assignment. The programs computed the balances and verdicts from those inputs.</p><p>We set the expected outcome before running the experiment. V1 counts approved waivers only, so this assignment should show ¥300 outstanding. We kept the ledger and the assignment terms fixed and varied whether a revision appeared during handoff and where the worker and reviewer got the procedure. That let us trace a changed verdict back to the way the procedure was selected.</p><p>In the first six runs, the rule stayed the same. We tried each worker approach three times. The current copy and assigned copy matched, all six reports showed ¥300 outstanding, and both checks passed every report. <strong>Those six runs gave us a baseline.</strong> In everyday work where the rules stand still, opening the latest copy can look entirely reliable. To tell the approaches apart, we needed an update after the task was assigned and before the next worker took it over.</p><p>That is what changed in the next six runs. Opening the latest copy produced three A reports. Retrieving the assigned copy produced three B reports. Each report then went through both review methods. Read across either row in the figure: <strong>the report stays put while a change in review basis flips the verdict.</strong> For this assignment, the current-only check passed all three A reports in error and rejected all three valid B reports. The assignment-based check got all six decisions right.</p><p><a href="/joinwell52/assets/sop-handoff-20261124/verdict-reader-v2.en.svg"><img src="'+d+`" alt="The same report passes under one review basis and is rejected under the other, shown for both reports"></a></p><p><em>Each cell shows three results. The four cells come from six reports, each reviewed two ways.</em></p><p>We used the official FCoP collaboration interfaces for tasks and reports. The assignment-based verdicts were filed as formal reviews of the corresponding reports. The harness controlled the handoff, accounting rules, and review methods. The results cover that controlled path. Live shift changes and business acceptance still need to be measured. <a href="/joinwell52/assets/sop-handoff-20261124/controlled-runs.json">Per-run balances, both verdicts, and whether a formal review was filed</a></p><h2 id="the-assignment-names-a-copy-nobody-can-open" tabindex="-1">The assignment names a copy nobody can open <a class="header-anchor" href="#the-assignment-names-a-copy-nobody-can-open" aria-label="Permalink to &quot;The assignment names a copy nobody can open&quot;">​</a></h2><p>For the last run, we kept the assignment’s reference and fingerprint, left the new version available, and took away the old text. The incoming program could identify the missing file. It had no text to tell it how the original procedure treated provisional waivers. <strong>The task stayed active. It produced neither a report nor a review.</strong> This one missing-file check adds a condition to the earlier result: the next shift needs to be able to retrieve the exact version the assignment references. A fingerprint helps verify the copy once you have it.</p><h2 id="can-the-next-shift-carry-on-with-the-same-job" tabindex="-1">Can the next shift carry on with the same job? <a class="header-anchor" href="#can-the-next-shift-carry-on-with-the-same-job" aria-label="Permalink to &quot;Can the next shift carry on with the same job?&quot;">​</a></h2><p>At shift change, reassignment, or restart, the system opens an assignment for someone new. <strong>A worker can take over only if they inherit the same job.</strong> When a procedure changes, the system needs to retain two facts: the rule the organization has now published, and the rule that governs this particular assignment. The publication record establishes the first. The original assignment or an authorized decision to move open work onto the new rule establishes the second. That is how the handoff can leave the pending ¥300 where it belongs.</p><p>In practice, the task needs to point to a retrievable copy of the applicable rule. The report records the version used and the ledger entries it relied on. Those linked records let the reviewing agent check the numbers and decide whether the work meets the original terms. If the historical copy is missing, the incoming agent needs to identify it and ask the responsible person to recover it.</p><h2 id="this-time-the-rule-really-changed-what-had-to-be-redone" tabindex="-1">This time the rule really changed. What had to be redone? <a class="header-anchor" href="#this-time-the-rule-really-changed-what-had-to-be-redone" aria-label="Permalink to &quot;This time the rule really changed. What had to be redone?&quot;">​</a></h2><p>We ran a follow-up. This time A and B were two separate assignments. <strong>The morning shift used two test accounts, one for reconciliation and one for review.</strong> Under the reconciliation account, the script checked the synthetic ¥2,700 payment, applied V1 to calculate zero eligible waiver, and filed both results in a record linked to the assignment. Under the review account, it checked the original inputs independently and recorded exactly which evidence it had verified. Both assignments stopped there, before a final report was filed.</p><p>After V2 was published, the test administrator approved B alone: keep the verified payment and reassess the waiver under the new rule. A’s request stayed pending. We reopened the CodeFlowMu task interface with <strong>two different test identities</strong>, one running reconciliation and one running review. Both recovered the morning’s records through the task interfaces. V2 was available to both assignments, but only B had an effective decision to switch.</p><p>We also set the checks for this round before running it. Both assignments had to recover the original payment verification, with zero new payment checks. A had to stay on V1 while its approval was pending. Only B could recalculate the waiver under V2. We checked those expectations against the file fingerprints, operation counts, and filed reviews.</p><table tabindex="0"><thead><tr><th>Assignment</th><th>Rule used after handoff</th><th style="text-align:right;">Payment reverifications</th><th style="text-align:right;">Waiver reassessment</th><th style="text-align:right;">Balance confirmed by the new reviewer</th></tr></thead><tbody><tr><td>A, switch pending</td><td>V1</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">¥300</td></tr><tr><td>B, switch approved</td><td>V2</td><td style="text-align:right;">0</td><td style="text-align:right;">One calculation and one review</td><td style="text-align:right;">¥0</td></tr></tbody></table><p>On both assignments, the payment verification records had identical file fingerprints before and after handoff. The operation log showed zero payment reverifications. B had one new waiver calculation and one independent review. We read back the two formal reviews and checked their links to the reports and earlier evidence. Only B cited an effective switch decision. <strong>This time we could account for B’s zero balance: the terms really had changed, and only the affected step was repeated.</strong> <a href="/joinwell52/assets/sop-handoff-20261124/selective-migration-runs.json">Both decisions, evidence fingerprints, and operation counts</a></p><p>This was one paired local comparison. Tasks, switch decisions, reports, and reviews went through the product interfaces. The two incoming identities were test accounts. The harness followed the approved list of steps to keep and repeat. A live handoff still needs to show whether AI agents can use the records to determine which earlier results are reusable.</p><h2 id="what-should-the-system-hand-over" tabindex="-1">What should the system hand over? <a class="header-anchor" href="#what-should-the-system-hand-over" aria-label="Permalink to &quot;What should the system hand over?&quot;">​</a></h2><p>StaffDeck’s fix shows why a procedure ID needs to survive a restart. Our two local experiments take that further: <strong>the handoff for an open assignment needs to say which rule applies, which results still stand, and which judgments have to be made again.</strong> In the first experiment, recalculating under the latest procedure let three incorrect reports pass and rejected three correct ones. In the follow-up, the approval applied to one assignment. Both kept their original payment evidence, and only the approved assignment reassessed the waiver. Those are observable checks for a digital employee system: after the accounts change, a change in outcome should still trace back to a decision on the specific assignment.</p><p><strong>The digital employee makes its own judgment, and another agent reviews the work independently.</strong> When the reconciliation agent receives A, it should check for an effective decision on that assignment before choosing the rule. If A reports zero, the review agent should open the assigned version, ask why the ¥300 was counted, and reach its own verdict. The organization’s rule owner authorizes which assignments move to the new version.</p><p>The <strong>workflow track</strong> carries the assignment, attempt, approved decision, and previous work records into the handoff. <strong>Tools</strong> return the original procedure, ledger entries, and receipts. <strong>Fact-checking</strong> verifies whether the agent actually performed the actions it claims, such as opening a particular version or invoking the payment verification tool. A receipt showing the agent opened V1 establishes that operation. The worker and reviewer still have to determine independently whether the waiver qualifies under V1.</p><h2 id="if-you-re-programming-the-next-agent-what-should-it-read-first" tabindex="-1">If you’re programming the next agent, what should it read first? <a class="header-anchor" href="#if-you-re-programming-the-next-agent-what-should-it-read-first" aria-label="Permalink to &quot;If you’re programming the next agent, what should it read first?&quot;">​</a></h2><p><strong>Recover the work from the formal records.</strong> The incoming worker gets the assignment ID and attempt, then reads the task, effective decisions, and evidence. The previous agent’s reasoning or chat can suggest where to look. The files establish how far the work got, which approval took effect, and whether a report was formally submitted.</p><p>To program the digital employee, give it three things:</p><ul><li><strong>The assignment tells it what to deliver.</strong> The reconciliation agent owes a report with the balance and its basis. The reviewing agent receives a reference to a specific report and delivers an independent assessment. The assignment and any effective decision for this attempt establish the procedure to apply.</li><li><strong>A role skill gives it a way to work.</strong> The reconciliation skill can guide the agent to inspect the handoff, work out which evidence still applies, and cite its sources. The review skill can ask the agent to examine the originals before comparing them with the report. Each agent chooses what to investigate and follows up when evidence is missing.</li><li><strong>MCP, the Model Context Protocol, exposes tools it can call.</strong> An agent uses tools to read assignments and reports, retrieve authorized materials, and file its report or review. The files and receipts returned by the tools give it facts to work from.</li></ul><p>FCoP, the File-based Coordination Protocol, gives the agents records they can retrieve and link: the assignment (<code>TASK</code>), report (<code>REPORT</code>), and review (<code>REVIEW</code>). A report’s <code>subject_ref</code> and <code>attempt_id</code> identify its assignment and attempt. A review’s <code>references</code> identify the specific report it assesses. <strong>The worker can submit a result. Delivery depends on an independent review by another agent.</strong> The reviewer makes its own assessment using the original evidence and procedure. A claim that the payment was checked needs a reference to the payment record and the receipt for the check.</p><p>In the experiment, CodeFlowMu let us read and write those records under separate test identities and look up approved instructions by assignment and attempt. Both assignments could open V2. A had no effective switch decision for the current attempt. B had a decision for its own assignment and attempt. The experiment exercised this sequence:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Worker: read TASK and attempt → retrieve effective decisions and source evidence → write REPORT → submit for review</span></span>
<span class="line"><span>Independent reviewer: read task, rule, and source evidence separately → check the specific REPORT → write REVIEW referencing it</span></span></code></pre></div><p>The script handled version selection and calculation under the approved list of steps. With live agents, FCoP still supplies the formal work records and CodeFlowMu still delivers the relevant context and tools. <strong>The worker and reviewer make their own judgments about what to investigate, what to redo, and whether the report meets the assignment.</strong> A filed “pass” shows who reviewed which report. The cited procedure and original evidence let us check whether that verdict holds up.</p><h2 id="what-did-the-second-agent-actually-check" tabindex="-1">What did the second agent actually check? <a class="header-anchor" href="#what-did-the-second-agent-actually-check" aria-label="Permalink to &quot;What did the second agent actually check?&quot;">​</a></h2><p>These experiments changed how we think about independent review. If two agents pick the same wrong rule, their separate calculations can agree exactly. They still share a faulty premise. That leads to a question: <strong>what would make a review add enough evidence to overturn the first answer?</strong> The same rent case gives us three ways to test it.</p><p><strong>Which comes first, the answer or the evidence?</strong> Could seeing “¥0 outstanding” anchor a live reviewer? We varied how the procedure was chosen in this study. The order in which reviewers see the evidence is a separate question. Give paired reviewers the same assignment, records, and report. One sees the report first. The other examines the source records and files a preliminary assessment before seeing the report. Include correct calculations under both the right and wrong versions. Set the expected verdicts from the assignments in advance and compare missed version errors and incorrect rejections. That tells us whether going to the source first improves review.</p><p><strong>Claiming you checked, checking, and understanding what you checked are three different things.</strong> Give a reviewer two contrasting records. In one, a report says the agent opened V1, but the complete log of the retrieval tool contains no matching call. In the other, the receipt confirms that the right copy was opened, yet the report deducts a ¥300 waiver that V1 disallows. The operation log answers the first claim. A separate review agent has to find the clause and explain the second error. Record the results separately to see whether the evidence trail or the role’s review guidance needs work.</p><p><strong>Which change warrants repeating which step?</strong> In the follow-up, the approval already said to keep the payment and recheck the waiver. Next, let the incoming agent identify the rework itself. Compare a change that affects only waiver eligibility with a case where the bank has reversed the payment. Give workers the same kind of assignments, records, and effective decisions, and have a separate reviewer check their proposals. In the first case, the payment verification can carry forward. In the second, the agent needs to reverify the payment and recalculate the balance. Count both missed rework and unnecessary repetition.</p><p>For each comparison, fix the task fixtures, model version, role skill, tools, and permissions. Decide what success looks like before changing the condition under test. FCoP files capture each agent’s verdict and references. Tool receipts record the actions each took.</p><p>The results will guide how we build these roles. If checking the originals first reduces missed version errors, we have grounds to put it in the review skill. If a critical action leaves no evidence, we can improve the tool receipt. If the incoming agent cannot tell what still applies, we can check whether the handoff files capture the relationship between the rule, evidence, and work performed. We’ll start with evidence order. <strong>What verifiable evidence does a second digital employee add, and when does it change the result?</strong></p></details>`,9))])}const y=s(c,[["render",l]]);export{v as __pageData,y as default};
